from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == grid[0][0] or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    return comps

def transform(grid):
    out = [row[:] for row in grid]
    bg = grid[0][0]
    comps = _components(grid)
    line = None
    elbow = None
    arms = None
    for color, cells in comps:
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
        if (len(cells) != (r1-r0+1)+(c1-c0+1)-1 or
                min(r1-r0+1, c1-c0+1) < 3):
            continue
        corners = [(r,c) for r,c in cells if ((r==r0 or r==r1) and (c==c0 or c==c1))]
        for r,c in corners:
            if all((r,x) in cells for x in range(c0,c1+1)) and all((y,c) in cells for y in range(r0,r1+1)):
                line=(color,cells); elbow=(r,c)
                arms=(1 if r==r0 else 0, 1 if c==c0 else 0)
                break
        if line:
            break
    if line is None:
        return out
    linecolor, linecells = line
    er,ec=elbow
    rdir,cdir=arms
    candidates=[]
    for color,cells in comps:
        if cells is linecells:
            continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        if rdir == 0:
            dr=0 if max(rs)>er else er-max(rs)+1
        else:
            dr=0 if min(rs)<er else min(rs)-er+1
        if cdir == 0:
            dc=0 if max(cs)>ec else ec-max(cs)+1
        else:
            dc=0 if min(cs)<ec else min(cs)-ec+1
        score=dr+dc
        candidates.append((score, -len(cells), color, cells))
    if candidates:
        _,_,targetcolor,target=min(candidates, key=lambda x:(x[0],x[1]))
        for r,c in target:
            out[r][c]=linecolor
    return out
